import type { ControlShell, ControlShellEvent } from '@selarikru/protocol';
import { redactSecrets } from '@selarikru/protocol';
import type { SbxCommandRunner, SbxStream } from './sbx.ts';

/** Session ids are generated by the control API; anything else never reaches a command line. */
const SAFE_SESSION = /^[A-Za-z0-9_-]{1,80}$/;
const MAX_LINE_CHARS = 1024 * 1024;
const PID_PREFIX = '/tmp/selarikru-control-';

/**
 * The guest half of control mode. Python is stdlib-only and present in the sandbox image (docs/evidence/spike-runtime.md); no native binding is added to the runner for it.
 *
 * It owns a PTY running a plain, non-readline bash in the workspace, and speaks JSON lines on stdin and stdout. The important frame is the ack: for each input it reads the
 * terminal's ECHO flag at the moment that input is written, on the master side, so `sudo` or `read -s` are seen for what they did. Nothing typed is ever kept here.
 *
 * Frames in:  {"i":seq,"d":"<base64 bytes>"}  and  {"x":1} to end.
 * Frames out: {"e":0|1} state, {"o":"<base64 bytes>"} output, {"a":seq,"e":0|1|null} ack (null: the write was not accepted), {"q":code} shell gone.
 */
export const CONTROL_HELPER = String.raw`
import base64, fcntl, json, os, pty, select, signal, struct, sys, termios, time
sid = sys.argv[1]
deadline = time.time() + 1800
pid_path = '${PID_PREFIX}' + sid + '.pid'
with open(pid_path, 'w') as f: f.write(str(os.getpid()))
pid, fd = pty.fork()
if pid == 0:
    env = {k: v for k, v in os.environ.items() if k not in ('BASH_ENV', 'ENV', 'PROMPT_COMMAND')}
    env.update(TERM='dumb', PAGER='cat', GIT_PAGER='cat', PS1='\\w \\$ \n', HISTFILE='/dev/null', HISTSIZE='0', COLUMNS='120', LINES='40')
    try:
        os.execvpe('bash', ['bash', '--noediting', '--noprofile', '--norc', '-i'], env)
    finally:
        os._exit(127)
fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', 40, 120, 0, 0))
flags = fcntl.fcntl(fd, fcntl.F_GETFL)
fcntl.fcntl(fd, fcntl.F_SETFL, flags | os.O_NONBLOCK)
def send(o):
    data = (json.dumps(o, separators=(',', ':')) + '\n').encode()
    while data:
        n = os.write(1, data)
        data = data[n:]
def echo():
    try:
        return 1 if termios.tcgetattr(fd)[3] & termios.ECHO else 0
    except Exception:
        return None
def stop(*_):
    try:
        os.killpg(pid, signal.SIGHUP)
        time.sleep(0.2)
        os.killpg(pid, signal.SIGKILL)
    except Exception:
        pass
    try:
        os.remove(pid_path)
    except Exception:
        pass
    sys.exit(0)
signal.signal(signal.SIGTERM, stop)
def write_all(data):
    end = time.time() + 1
    while data and time.time() < end:
        try:
            n = os.write(fd, data)
            data = data[n:]
        except BlockingIOError:
            select.select([], [fd], [], 0.05)
        except OSError:
            return False
    return not data
last = echo()
send({'e': last})
buf = b''
code = 0
while time.time() < deadline:
    try:
        rd, _, _ = select.select([fd, 0], [], [], 0.05)
    except InterruptedError:
        continue
    if fd in rd:
        try:
            chunk = os.read(fd, 16384)
        except BlockingIOError:
            chunk = None
        except OSError:
            chunk = b''
        if chunk == b'':
            break
        if chunk is not None:
            state = echo()
            if state != last:
                last = state
                send({'e': state})
            send({'o': base64.b64encode(chunk).decode()})
    if 0 in rd:
        data = os.read(0, 65536)
        if not data:
            break
        buf += data
        if len(buf) > 2000000:
            break
        while b'\n' in buf:
            line, buf = buf.split(b'\n', 1)
            try:
                msg = json.loads(line)
            except Exception:
                continue
            if msg.get('x'):
                stop()
            if 'i' in msg and 'd' in msg:
                try:
                    state = echo()
                    ok = write_all(base64.b64decode(msg['d']))
                    send({'a': msg['i'], 'e': state if ok else None})
                except Exception:
                    send({'a': msg.get('i'), 'e': None})
    now_state = echo()
    if now_state != last:
        last = now_state
        send({'e': now_state})
try:
    send({'q': code})
except Exception:
    pass
stop()
`;

export const controlShellArgs = (sandboxId: string, workspace: string, sessionId: string): string[] => {
  if (!SAFE_SESSION.test(sessionId)) throw new Error('invalid control session id');
  return ['exec', '-i', '-w', workspace, sandboxId, 'python3', '-c', CONTROL_HELPER, sessionId];
};

/** The stop for when the host client cannot reach it: killing `sbx exec` does not end the process in the sandbox (spike section 5). */
export const controlKillArgs = (sandboxId: string, sessionId: string): string[] => {
  if (!SAFE_SESSION.test(sessionId)) throw new Error('invalid control session id');
  const f = `${PID_PREFIX}${sessionId}.pid`;
  return ['exec', sandboxId, 'sh', '-c', `f=${f}; [ -s "$f" ] && kill -TERM "$(cat "$f")" 2>/dev/null; rm -f "$f"; exit 0`];
};

const closed: ControlShellEvent = { kind: 'exited' };

/** Reads the helper's frames. An unreadable frame is dropped, never shown or trusted. A frame's fields are only taken as what they are: output is bytes for the redactor, acks are numbers. */
export class SbxControlShell implements ControlShell {
  private readonly decoder = new TextDecoder('utf-8');
  private ending: Promise<void> | null = null;
  private ended = false;

  constructor(private readonly stream: SbxStream, private readonly sbx: SbxCommandRunner, private readonly sandboxId: string, private readonly sessionId: string, private readonly killMs = 5_000) {}

  get events(): AsyncIterable<ControlShellEvent> {
    return this.read();
  }

  private async *read(): AsyncGenerator<ControlShellEvent> {
    let held = '';
    for await (const chunk of this.stream.output) {
      held += chunk;
      if (held.length > MAX_LINE_CHARS) { held = ''; continue; }
      for (let i = held.indexOf('\n'); i >= 0; i = held.indexOf('\n')) {
        const line = held.slice(0, i);
        held = held.slice(i + 1);
        const ev = this.frame(line);
        if (ev !== null) yield ev;
      }
    }
    const tail = this.decoder.decode();
    if (tail !== '') yield { kind: 'output', text: tail };
    this.ended = true;
    yield closed;
  }

  private frame(line: string): ControlShellEvent | null {
    let o: unknown;
    try {
      o = JSON.parse(line);
    } catch {
      return null;
    }
    if (typeof o !== 'object' || o === null) return null;
    const f = o as Record<string, unknown>;
    const echo = (v: unknown): boolean | null => (v === 1 ? true : v === 0 ? false : null);
    if (typeof f['o'] === 'string') return { kind: 'output', text: this.decoder.decode(Buffer.from(f['o'], 'base64'), { stream: true }) };
    if (typeof f['a'] === 'number') return { kind: 'ack', seq: f['a'], echo: echo(f['e']) };
    if ('q' in f) return closed;
    if ('e' in f) {
      const on = echo(f['e']);
      return on === null ? null : { kind: 'echo', on };
    }
    return null;
  }

  input(seq: number, data: string): void {
    if (this.ended || this.ending !== null) return;
    this.stream.stdin.write(`${JSON.stringify({ i: seq, d: Buffer.from(data, 'utf8').toString('base64') })}\n`);
  }

  /** Bounded. Never leaves a shell behind in the sandbox: it asks, then waits, then kills inside the guest, because killing the host client does not. */
  close(): Promise<void> {
    if (this.ending === null) this.ending = this.shutdown();
    return this.ending;
  }

  private async shutdown(): Promise<void> {
    if (!this.ended) {
      this.stream.stdin.write(`${JSON.stringify({ x: 1 })}\n`);
      this.stream.stdin.end();
    }
    const exited = await Promise.race([this.stream.exited.then(() => true), new Promise<boolean>((r) => setTimeout(() => r(false), 2_000))]);
    if (!exited) {
      try {
        await this.sbx.run(controlKillArgs(this.sandboxId, this.sessionId), { timeoutMs: this.killMs });
      } catch (err) {
        void redactSecrets(err instanceof Error ? err.message : 'error');
      }
      this.stream.kill();
    }
    this.ended = true;
  }
}
